// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 minSum) internal {
        try c.SetMinSum(minSum) {} catch { return; }
        bool revertedBefore;
        try c.SetLogFile(address(this)) { revertedBefore = false; } catch { revertedBefore = true; }
        try c.Initialized() {} catch { return; }
        bool revertedAfter;
        try c.SetLogFile(address(this)) { revertedAfter = false; } catch { revertedAfter = true; }
        assertTrue(!revertedBefore && revertedAfter);
    }

    function testFuzz_run(uint256 minSum) public {
        _run(minSum);
    }

    receive() external payable {}
}
